sctp_disposition_t sctp_handle_cookie_echo(const struct sctp_endpoint *ep,
                                           const struct sctp_association *asoc,
                                           sctp_subtype_t type,
                                           void *arg,
                                           sctp_cmd_seq_t *commands,
                                           struct net *net)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_NOCLOSE;
    struct sctp_chunk *chunk = (struct sctp_chunk *)arg;
    struct sctp_cookie *cookie;
    int error;

    if (!chunk || chunk->skb->len < sizeof(struct sctp_cookie)) {
        return SCTP_DISPOSITION_DISCARD;
    }

    cookie = sctp_get_cookie(chunk->skb);
    if (!cookie) {
        return SCTP_DISPOSITION_DISCARD;
    }

    error = sctp_unpack_cookie(chunk->skb, cookie);
    if (error < 0) {
        disposition = SCTP_DISPOSITION_DISCARD;
        goto out;
    }

    if (cookie->vtag != asoc->cmy_vtag) {
        sctp_cmd_seq_add(commands, SCTP_CMD_INIT_FAILED, cookie->vtag);
        disposition = SCTP_DISPOSITION_DISCARD;
        goto out;
    }

    if (sctp_handle_collision(cookie, asoc)) {
        sctp_cmd_seq_add(commands, SCTP_CMD_ASSOC_RESTART, NULL);
    }

    sctp_cmd_seq_add(commands, SCTP_CMD_UPDATE_COOKIE, cookie);

out:
    kfree(cookie);
    return disposition;
}

sctp_disposition_t sctp_handle_cookie_echo(
    struct net *net,
    const struct sctp_endpoint *ep,
    const struct sctp_association *asoc,
    sctp_subtype_t type,
    void *arg,
    sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_cookie_param_t *state_cookie;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;

    if (chunk->chunk_hdr->length < sizeof(sctp_cookie_param_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    state_cookie = sctp_get_param(chunk, SCTP_PARAM_STATE_COOKIE, sizeof(sctp_cookie_param_t));
    if (!state_cookie) {
        return SCTP_DISPOSITION_BAD;
    }

    if (sctp_unpack_state_cookie(net, asoc, state_cookie) < 0) {
        if (asoc->verified_tag != chunk->subh->cookie_echo_hdr->vtag) {
            disposition = SCTP_DISPOSITION_NOMEM;
        } else {
            sctp_cmd_seq_append(commands, SCTP_CMD_NEW_ASOC, NULL);
        }
    } else if (asoc->c.my_vtag == chunk->subh->cookie_echo_hdr->vtag) {
        sctp_cmd_seq_append(commands, SCTP_CMD_INIT_TAG, NULL);
    } else {
        disposition = SCTP_DISPOSITION_DISCARD;
    }

    return disposition;
}

sctp_disposition_t sctp_handle_dup_cookie_echo(struct net *net,
                                              const struct sctp_endpoint *ep,
                                              const struct sctp_association *asoc,
                                              sctp_subtype_t type,
                                              void *arg,
                                              sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    struct sctp_chunk *chunk = arg;
    int error;

    /* Validate chunk length */
    if (chunk->chunk_hdr->length < sizeof(sctp_chunkhdr_t) + sizeof(sctp_cookie_echo_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    /* Decode chunk and unpack state cookie */
    error = sctp_unpack_cookie(chunk, asoc);
    if (error) {
        return SCTP_DISPOSITION_BAD;
    }

    /* Compare verification tags */
    if (asoc->c.my_vtag != asoc->c.peer_vtag) {
        sctp_cmd_init(commands, SCTP_CMD_INIT, NULL);
    } else {
        sctp_cmd_init(commands, SCTP_CMD_NOP, NULL);
    }

    return disposition;
}

sctp_disposition_t sctp_handle_dup_cookie_echo(struct net *net,
                                              const struct sctp_endpoint *ep,
                                              const struct sctp_association *asoc,
                                              sctp_subtype_t type,
                                              void *arg,
                                              sctp_cmd_seq_t *commands)
{
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    struct sctp_chunk *chunk = (struct sctp_chunk *)arg;
    int error = 0;

    if (!chunk || chunk->length < sizeof(sctp_cookie_echo_chunk_t))
        return SCTP_DISPOSITION_NOMEM;

    /* Decode the chunk */
    if (sctp_process_cookie(net, ep, asoc, chunk, commands) < 0) {
        sctp_cmd_init(commands, SCTP_CMD_NOP, 0);
        return SCTP_DISPOSITION_DISCARD;
    }

    /* Compare verification tags */
    if (asoc && asoc->verified_tag != chunk->subh.cookie_echo_hdr->verification_tag) {
        sctp_cmd_init(commands, SCTP_CMD_INIT_TAG, asoc->verified_tag);
        disposition = SCTP_DISPOSITION_NOMEM;
    }

    return disposition;
}

sctp_disposition_t sctp_handle_dup_cookie_echo(struct net *net,
                                              const struct sctp_endpoint *ep,
                                              const struct sctp_association *asoc,
                                              sctp_subtype_t type,
                                              void *arg,
                                              sctp_cmd_seq_t *commands)
{
    sctp_chunk_t *chunk = (sctp_chunk_t *)arg;
    sctp_disposition_t disposition = SCTP_DISPOSITION_CONSUME;
    sctp_cookie_preserve_t *cookie;
    int len;

    /* Validate chunk length */
    if (chunk->chunk_hdr->length < sizeof(sctp_chunk_t)) {
        return SCTP_DISPOSITION_NOMEM;
    }

    len = ntohs(chunk->chunk_hdr->length);
    if (len < sizeof(sctp_cookie_preserve_t)) {
        return SCTP_DISPOSITION_BAD;
    }

    cookie = sctp_unpack_cookie(net, chunk->skb, 0, len);
    if (!cookie) {
        return SCTP_DISPOSITION_NOMEM;
    }

    if (!sctp_cookie_verify(net, asoc, cookie)) {
        sctp_cmd_sf(commands, SCTP_CMD_INIT_PEER, SCTP_NULL);
        disposition = SCTP_DISPOSITION_NOREPLY;
    } else if (ntohl(asoc->c.peer.init_tag) != ntohl(cookie->init_tag)) {
        sctp_cmd_sf(commands, SCTP_CMD_TAG_COLLISION, SCTP_NULL);
        disposition = SCTP_DISPOSITION_NOREPLY;
    } else {
        sctp_cmd_sf(commands, SCTP_CMD_DISCARD_PACKET, SCTP_NULL);
    }

    kfree(cookie);
    return disposition;
}
